double energy(const juce::AudioBuffer<float>& b){double sum=0;for(int c=0;c<b.getNumChannels();++c)for(int i=0;i<b.getNumSamples();++i)sum+=b.getSample(c,i)*b.getSample(c,i);return sum;}
